   383  l_ok
   384  pixWriteStreamBmp(FILE  *fp,
   385                    PIX   *pix)
   386  {
   387  l_uint8  *data;
   388  size_t    size, nbytes;
   389
   390      PROCNAME("pixWriteStreamBmp");
   391
   392      if (!fp)
   393          return ERROR_INT("stream not defined", procName, 1);
   394      if (!pix)
   395          return ERROR_INT("pix not defined", procName, 1);
   396
   397      pixWriteMemBmp(&data, &size, pix);
   398      rewind(fp);
   399      nbytes = fwrite(data, 1, size, fp);
   400      free(data);
   401      if (nbytes != size)
   402          return ERROR_INT("Write error", procName, 1);
   403      return 0;
   404  }
