   407  /*!
   408   * \brief   pixWriteMemBmp()
   409   *
   410   * \param[out]   pfdata   data of bmp formatted image
   411   * \param[out]   pfsize    size of returned data
   412   * \param[in]    pixs      1, 2, 4, 8, 16, 32 bpp
   413   * \return  0 if OK, 1 on error
   414   *
   415   * <pre>
   416   * Notes:
   417   *      (1) 2 bpp bmp files are not valid in the original spec, and are
   418   *          written as 8 bpp.
   419   *      (2) pix with depth <= 8 bpp are written with a colormap.
   420   *          16 bpp gray and 32 bpp rgb pix are written without a colormap.
   421   *      (3) The transparency component in an rgb pix is ignored.
   422   *          All 32 bpp pix have the bmp alpha component set to 255 (opaque).
   423   *      (4) The bmp colormap entries, RGBA_QUAD, are the same as
   424   *          the ones used for colormaps in leptonica.  This allows
   425   *          a simple memcpy for bmp output.
   426   * </pre>
   427   */
   428  l_ok
   429  pixWriteMemBmp(l_uint8  **pfdata,
   430                 size_t    *pfsize,
   431                 PIX       *pixs)
   432  {
   433  l_uint8     pel[4];
   434  l_uint8    *cta = NULL;     /* address of the bmp color table array */
   435  l_uint8    *fdata, *data, *fmdata;
   436  l_int32     cmaplen;      /* number of bytes in the bmp colormap */
   437  l_int32     ncolors, val, stepsize;
   438  l_int32     w, h, d, fdepth, xres, yres;
   439  l_int32     pixWpl, pixBpl, extrabytes, fBpl, fWpl, i, j, k;
   440  l_int32     heapcm;  /* extra copy of cta on the heap ? 1 : 0 */
   441  l_uint32    offbytes, fimagebytes;
   442  l_uint32   *line, *pword;
   443  size_t      fsize;
   444  BMP_FH     *bmpfh;
   445  #if defined(__GNUC__)
   446  BMP_HEADER *bmph;
   447  #define bmpih (&bmph->bmpih)
   448  #else
   449  BMP_IH     *bmpih;
   450  #endif
   451  PIX        *pix;
   452  PIXCMAP    *cmap;
   453  RGBA_QUAD  *pquad;
   454
   455      PROCNAME("pixWriteMemBmp");
   456
   457      if (pfdata) *pfdata = NULL;
   458      if (pfsize) *pfsize = 0;
   459      if (!pfdata)
   460          return ERROR_INT("&fdata not defined", procName, 1 );
   461      if (!pfsize)
   462          return ERROR_INT("&fsize not defined", procName, 1 );
   463      if (!pixs)
   464          return ERROR_INT("pixs not defined", procName, 1);
   465
   466      pixGetDimensions(pixs, &w, &h, &d);
   467      if (d == 2) {
   468          L_WARNING("2 bpp files can't be read; converting to 8 bpp\n", procName);
   469          pix = pixConvert2To8(pixs, 0, 85, 170, 255, 1);
   470          d = 8;
   471      } else {
   472          pix = pixCopy(NULL, pixs);
   473      }
   474      fdepth = (d == 32) ? 24 : d;
   475
   476          /* Resolution is given in pixels/meter */
   477      xres = (l_int32)(39.37 * (l_float32)pixGetXRes(pix) + 0.5);
   478      yres = (l_int32)(39.37 * (l_float32)pixGetYRes(pix) + 0.5);
   479
   480      pixWpl = pixGetWpl(pix);
   481      pixBpl = 4 * pixWpl;
   482      fWpl = (w * fdepth + 31) / 32;
   483      fBpl = 4 * fWpl;
   484      fimagebytes = h * fBpl;
   485      if (fimagebytes > 4LL * L_MAX_ALLOWED_PIXELS) {
   486          pixDestroy(&pix);
   487          return ERROR_INT("image data is too large", procName, 1);
   488      }
   489
   490          /* If not rgb or 16 bpp, the bmp data is required to have a colormap */
   491      heapcm = 0;
   492      if (d == 32 || d == 16) {   /* 24 bpp rgb or 16 bpp: no colormap */
   493          ncolors = 0;
   494          cmaplen = 0;
   495      } else if ((cmap = pixGetColormap(pix))) {   /* existing colormap */
   496          ncolors = pixcmapGetCount(cmap);
   497          cmaplen = ncolors * sizeof(RGBA_QUAD);
   498          cta = (l_uint8 *)cmap->array;
   499      } else {   /* no existing colormap; d <= 8; make a binary or gray one */
   500          if (d == 1) {
   501              cmaplen  = sizeof(bwmap);
   502              ncolors = 2;
   503              cta = (l_uint8 *)bwmap;
   504          } else {   /* d = 2,4,8; use a grayscale output colormap */
   505              ncolors = 1 << fdepth;
   506              cmaplen = ncolors * sizeof(RGBA_QUAD);
   507              heapcm = 1;
   508              cta = (l_uint8 *)LEPT_CALLOC(cmaplen, 1);
   509              stepsize = 255 / (ncolors - 1);
   510              for (i = 0, val = 0, pquad = (RGBA_QUAD *)cta;
   511                   i < ncolors;
   512                   i++, val += stepsize, pquad++) {
   513                  pquad->blue = pquad->green = pquad->red = val;
   514                  pquad->alpha = 255;  /* opaque */
   515              }
   516          }
   517      }
